import React, { useState,useEffect }from 'react';
import { Button,message,Layout,Col,EditOutlined,Row } from 'antd';
import {UserOutlined } from '@ant-design/icons';
import PatientView from './PatientView.tsx'
import axios from './axios.js';



const PatientList=()=>{
    const [userList,setUserList] = useState([]);
    const [loading,setLoading] = useState(true);
    const [displayItem,setDisplayItem] = useState([]);
    const [messageApi,contextHolder] = message.useMessage();


    useEffect(()=>{

        const getPatients = async ()=>{
            try{
                const response = await axios.get('/patients');
                setUserList(response.data);
                  
            }catch (error) {
                messageApi.error('无法获取数据');
                  
            } 

        }
        getPatients();
        setLoading(false);

    },[userList,messageApi]);

    if (loading) return <div>加载中</div>;

    console.log(displayItem);
    return(
        <Layout>
        <div>{contextHolder}</div>
        <ul>
        <Row>
            <Col xs={2}>
           
        {
            userList.map(item=>(

                <li key={item.personalInfo.name} onClick={()=>setDisplayItem(userList.filter(a=>a.personalInfo.name===item.personalInfo.name))}><Button>{item.personalInfo.name}</Button></li>
                ))
        }
            </Col>
            

            {
                displayItem.map(item=>(
                        <Col xs={6}>
                            <PatientView data={item} />
                        </Col>
                    ))
            }
            
        </Row>
        </ul>
        </Layout>
    );
    
};

export default PatientList;